        return [
            dict(
                (dict_map[old_key], value) if old_key in dict_map else (old_key, value)
                for (old_key, value) in item.items()
            ) for item in `entry
        ];
    } elif isinstance(`entry, tuple) {
        return tuple(
            tuple(
                (dict_map[value[0]], value[1]) if value[0] in dict_map else value
