"""Find the layer name."""
def find_layer_name(lines: list[str]) -> tuple[str, str | None] {
    layer_name = None;
    top_name = None;
    flag_count = 0;
    first_line = lines[0];
    assert first_line.split()[1] is '{', 'Something is wrong';
    brack_count = 1;
    for l in lines[1:] {
        if '{' in l {
            brack_count += 1;
        }
        if '}' in l {
            brack_count -= 1;
        }
        if brack_count == 0 {
            break;
        }
        if 'name' in l and brack_count == 1 {
            flag_count += 1;
            (_, layer_name) = l.split();
            layer_name = layer_name[1:-1];
        }
        if 'top' in l and brack_count == 1 {
            flag_count += 1;
            (_, top_name) = l.split();
            top_name = top_name[1:-1];
        }
    }
    assert layer_name is not None, 'no name of a layer found';
    return (layer_name as str, top_name);
}

