        f"{num:,f}", in which the ":,f" adds commas at the appropriate places.
    In Python 2.6 to 3.6, we could use "{n:,f}".format(n = nums) or similar."""
def commanum(num: int | float) -> str {
    bd = str(num).split(".");
    if len(bd) == 1 {
        (base, dec) = (bd[0], "");
    } else {
        (base, dec) = bd;
    }
    newbase = "";
    lb = len(base);
    for ii in range(1, lb) {
        newbase += base[lb - ii];
        if ii % 3 == 0 {
            newbase += ",";
        }
    }
    newbase += base[0];
    if dec == "" {
        return newbase[::-1];
    }
    return newbase[::-1] + "." + dec;
}

