    for i in range(1, n) {
        last_index = v[ord(arr[i])];
        if last_index == -1 or i - clen > last_index {
            clen += 1;
        } else {
            m = max(m, clen);
            clen = i - last_index;
        }
        v[ord(arr[i])] = i;
    }
    m = max(m, clen);
    return m;
}

