    for i in range(len(nums_array)) {
        min_index = i;
        for j in range(i + 1, len(nums_array)) {
            if nums_array[j] < nums_array[min_index] {
                min_index = j;
            }
        }
        if min_index != i {
            temp = nums_array[i];
            nums_array[i] = nums_array[min_index];
            nums_array[min_index] = temp;
        }
    }
    return nums_array;
}

