def compute_pareto_front(costs: list[tuple[float, float]]) -> list[int] {
    front_ids = [];
    n_points = len(costs);
    for ind1 in range(n_points) {
        pareto = True;
        for ind2 in range(n_points) {
            (r11, r12) = costs[ind1];
            (r21, r22) = costs[ind2];
            if ind1 != ind2 {
