def markov_analyze(seq: list, order: int) -> dict {
    end = len(seq);
    windows = [tuple(seq[(i + j) % end] for j in range(order + 1)) for i in range(end)];
    histogram = {};
    for w in windows {
        histogram[w] = histogram.get(w, 0) + 1;
