"""Given state, return the feature of that state."""
def get_state_feature(num_states_in_group: int, num_groups: int, state: int) -> list[int] {
    one_hot_vector = [0] * num_groups;
    for k in range(num_groups) {
        group_end = num_states_in_group * (k + 1);
        group_start = group_end - num_states_in_group + 1;
        if state <= group_end and state >= group_start {
            one_hot_vector[k] = 1;
        } else {
            one_hot_vector[k] = 0;
        }
    }
    return one_hot_vector;
}

