    Using "date"(str) length, judge date type.
    Args:
        date (str): date

    Returns:
        str:
    """
def judge_date_type(date: str) -> str {
    match len(date) {
        case 8:
            date_type = "day";
        case 6:
            date_type = "month";
        case 4:
            date_type = "year";
        case _:
            raise Exception(f'{date} is not valid value.');
    }
    return date_type;
}

