        length = 8;
    } elif cur_time >= 86400 {
        minute = round((cur_time % 86400 % 3600) / 60);
        hour = round((cur_time % 86400) / 3600);
        day = round(cur_time / 86400);
        stand_time = '{:02d}d{:02d}h{:02d}min'.format(day, hour, minute);
        length = 11;
    } else {
        second = round(cur_time);
        stand_time = '00:{:02d}'.format(second);
        length = 5;
