def split_quoted(message: str) -> list[str] {
    pos = -1;
    inquote = False;
    buffer = "";
    final: list[str] = [];
    while pos < len(message) - 1 {
        pos += 1;
        token = message[pos];
        if token == " " and not inquote {
            final.append(buffer);
            buffer = "";
            continue;
        }
