"""Squeeze a sequence."""
def squeeze(data: list[int]) -> tuple[list[int], list[int]] {
    count = [1];
    values = [data[0]];
    for value in data[1:] {
        if value == values[-1] {
            count[-1] += 1;
        } else {
            values.append(value);
            count.append(1);
        }
    }
    return (count, values);
}

