    """
def mid_point(bboxes: list[list[int]]) -> list[tuple[int, int]] {
    mid_values = list();
    for coor in bboxes {
        x1 = coor[0];
        y1 = coor[1];
        x2 = coor[2];
        y2 = coor[3];
