"""Get the number of the argument at position pos in a string without interpreting quotes."""
def _find_argument_unquoted(pos: int, text: str) -> int {
    ret = text.split();
    search = 0;
    argnum = 0;
    for (i, elem) in enumerate(ret) {
        elem_start = text.find(elem, search);
        elem_end = elem_start + len(elem);
        search = elem_end;
        if elem_start <= pos < elem_end {
            return i;
        }
        argnum = i;
    }
    return argnum + 1;
}

