        s = s.replace('=', '\\=');
        s = s.replace('\000', '\\\000');
        if s[0] in ('#', ' ') {
            s = ''.join(('\\', s));
        }
        if s[-1] == ' ' {
            s = ''.join((s[:-1], '\\ '));
        }
    }
    return s;
}

