    if not text {
        return text;
    }
    res = text[0];
    c_prev = text[0];
    n_reps = 0;
    for c in text[1:] {
        if c == c_prev {
            n_reps += 1;
            if n_reps < 2 {
                res += c;
            }
        } else {
