def _calculate_cut(lemmawords: set[str] | list[str], stems: dict[str, set[str] | list[str]]) -> tuple[float, float] {
    (umt, wmt) = (0.0, 0.0);
    for stem in stems {
        cut = set(lemmawords) & set(stems[stem]);
        if cut {
            cutcount = len(cut);
            stemcount = len(stems[stem]);
