    if l == 10 {
        return int(v);
    } elif l == 13 {
        return int(v / 1000);
    } elif l == 16 {
        return int(v / (1000 ** 2));
    } elif l == 19 {
        return int(v / (1000 ** 3));
    } else {
        raise ValueError('invalid time length, not 10, 13, 16 or 19: {v}'.format(v=v));
    }
}

