Fit theta such that phi_i = theta * i + phi_0.
"""
def fit_simulaid(phi: list[float]) -> float {
    n = len(phi) - 1;
    a11 = ((2 * n) + 1) * (n + 1) * n / 6;
    a21 = n * (n + 1) / 2;
