"""o(log(m)+log(n)) solution n=sizeof a ,m=sizeof b"""
def kthSmall(A: list[int], B: list[int], k: int) -> int {
    if not A {
        return B[k];
    } elif not B {
        return A[k];
    }
    ia = len(A) // 2;
    ib = len(B) // 2;
    ma = A[ia];
    mb = B[ib];
    if ia + ib < k {
        if ma > mb {
            return kthSmall(A, B[(ib + 1):], k - (ib + 1));
        }
        return kthSmall(A[(ia + 1):], B, k - (ia + 1));
    } elif ma > mb {
        return kthSmall(A[:ia], B, k);
    }
    return kthSmall(A, B[:ib], k);
}

