    """
def sum_list_constraint(in_list: list[int], value: int) -> list[int] {
    shallow_list = [];
    for element in in_list {
        if element > value {
            continue;
        }
        if element == value {
            value = 0;
            shallow_list.append(element);
            break;
        }
        if element < value {
            shallow_list.append(element);
            value -= element;
        }
    }
    if value != 0 {
        return [];
    }
    return shallow_list;
}

